#!/usr/bin/env node
// generate-index - derive INDEX.md and the category tables from entry frontmatter.
//
// An index maintained by hand omits whatever nobody remembered to add, and nothing detects the
// omission. Three entries went missing that way before this existed. Deriving the index from the
// entries makes that class impossible rather than merely fixed: the entry is the only place a fact
// is written, and every table is a projection of it.
//
// Generated regions are delimited, so hand-written prose in the same file survives untouched:
//
//   <!-- BEGIN GENERATED: entries. Run tools/generate-index.mjs; do not edit by hand. -->
//   <!-- END GENERATED -->
//
// A file with no markers is left alone, which is how roles/, domains/ and work-types/ opt out of
// carrying a local table.
//
// Exit non-zero in --check mode when a generated region is stale. That is the half that makes the
// guarantee hold: generation without a failing check is a convention, not a mechanism.
//
// Usage:  node tools/generate-index.mjs           rewrite every generated region
//         node tools/generate-index.mjs --check   fail if any region is out of date

import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const BEGIN = '<!-- BEGIN GENERATED: entries. Run tools/generate-index.mjs; do not edit by hand. -->';
const END = '<!-- END GENERATED -->';

// The layer set is not declared here. It is read from the corpus twice, from two places that are
// maintained for other reasons, and the two are held against each other.
//
//   order  - the root charter's layer table, which is the authored reading order
//   set    - the directories that carry a charter, which is what makes a layer self-describing
//
// A list here would be a third statement of a fact the corpus already makes twice, and it was:
// it had drifted into a different sequence of the same thirteen layers, and nothing noticed while
// the ledger was flat and its order invisible. Adding a layer is now an edit to the corpus and
// never to this tool. A prefix is not needed at all - it was only ever used to rank entries for
// sorting, which the layer order does directly.

function frontmatter(text) {
	const m = text.match(/^---\n([\s\S]*?)\n---/);
	if (!m) return null;
	const out = {};
	let key = null;
	for (const raw of m[1].split('\n')) {
		const line = raw.replace(/\s+#.*$/, '');
		// A block list - "members:" then "  - ID" lines - is read as the same [a, b] form an inline
		// list takes, so a set's members cannot silently read as empty.
		const item = line.match(/^\s+-\s+(.*)$/);
		if (item && key) { out[key] = out[key] ? out[key].replace(/\]$/, `, ${item[1].trim()}]`).replace('[, ', '[') : `[${item[1].trim()}]`; continue; }
		const kv = line.match(/^([A-Za-z][\w-]*):\s*(.*)$/);
		if (!kv) { key = null; continue; }
		key = kv[1];
		out[kv[1]] = kv[2].trim().replace(/^["']|["']$/g, '');
	}
	return out;
}

// The authored reading order: the root charter's layer table, minus the mechanism layers, which
// declare '-' for a prefix and appear in no ledger.
function layersFromCharter() {
	const readme = readFileSync(path.join(ROOT, 'README.md'), 'utf8');
	return [...readme.matchAll(/^\| *`?([A-Z-]+)`? *\| *\[`([a-z-]+)\/`\]/gm)]
		.filter((m) => m[1] !== '-').map((m) => m[2]);
}

// What is actually on disk: a directory carrying a charter, which is a README declaring both an id
// and a category. That predicate is only exact because every layer has a charter; before they did,
// it would have found four of thirteen.
function layersOnDisk() {
	return readdirSync(ROOT, { withFileTypes: true })
		.filter((d) => d.isDirectory() && !d.name.startsWith('.') && d.name !== 'node_modules')
		.map((d) => d.name)
		.filter((name) => {
			const readme = path.join(ROOT, name, 'README.md');
			if (!existsSync(readme)) return false;
			const fm = frontmatter(readFileSync(readme, 'utf8'));
			return Boolean(fm && fm.id && fm.category);
		});
}

// Held against each other before anything is read. A layer in one and not the other is a layer
// whose entries would silently not be collected, or a heading with nothing under it, and the
// ledger would look correct either way.
const LAYERS = layersFromCharter();
const onDisk = layersOnDisk();
const missing = onDisk.filter((d) => !LAYERS.includes(d));
const phantom = LAYERS.filter((d) => !onDisk.includes(d));
if (missing.length || phantom.length) {
	for (const d of missing) console.error(`FAIL  layer set  ${d}/ carries a charter but the root README layer table does not list it`);
	for (const d of phantom) console.error(`FAIL  layer set  the root README layer table lists ${d}/, which carries no charter`);
	console.error('\nThe charter table and the directories that carry charters must name the same layers.');
	process.exit(1);
}

// Collect every entry that declares an id, from the category directory that owns it.
function collect() {
	const entries = [];
	for (const dir of LAYERS) {
		const abs = path.join(ROOT, dir);
		if (!existsSync(abs)) continue;
		for (const file of readdirSync(abs)) {
			// An entry is a file in the category directory. A skill's portable SKILL.md is not
			// an entry: it carries no catalogue placement, because an id, a status and a
			// ledger title are meaningless once the skill is lifted into another repository.
			// The K* stub beside it is the entry, and it points at the body.
			const candidates = file.endsWith('.md') ? [`${dir}/${file}`] : [];
			for (const rel of candidates) {
				const fm = frontmatter(readFileSync(path.join(ROOT, rel), 'utf8'));
				if (!fm || !fm.id) continue;
				entries.push({ ...fm, dir, rel });
			}
		}
	}
	return entries;
}

// Sort by category order, then numerically inside it, so A9 precedes A10.
const num = (id) => Number((id.match(/(\d+)$/) || [0, 0])[1]);
function ordered(entries) {
	const rank = new Map(LAYERS.map((dir, i) => [dir, i]));
	return [...entries].sort((a, b) =>
		(rank.get(a.dir) - rank.get(b.dir)) || (num(a.id) - num(b.id)));
}

const cell = (s) => String(s ?? '').replace(/\|/g, '\\|').trim();

// A layer's display name is its directory name. The charter's title must begin with the same word,
// so the heading has two independent derivations gated against each other rather than one nobody
// can check. See headingDisagreements.
const headingOf = (dir) => dir[0].toUpperCase() + dir.slice(1);

// Status is emitted only where some row is not active. Nearly every entry is, so a column
// restating it is ballast in a file that loads into every session.
// Enforcement is emitted only in a layer's own table, and only where some member names an
// enforcer. The member's enforced-by is the one declaration; this column is its reverse view, so
// a charter can say which rules a script holds without keeping a second list that drifts. The
// ledger omits it: it loads into every session and routes by condition, not by enforcement.
function table(entries, linkFrom, { enforcement = false } = {}) {
	const withStatus = entries.some((e) => e.status !== 'active');
	const withEnforcer = enforcement && entries.some((e) => e['enforced-by']);
	// The same reverse view for an axiom's applies-to: which systems' traits bring it into force,
	// declared once on the axiom and shown here so the charter need keep no applicability matrix.
	const withApplies = enforcement && entries.some((e) => e['applies-to']);
	// And for an artifact type's instance-path: where every project puts an instance, declared on
	// the type and shown here, so the artifacts charter keeps the rule and names no member.
	const withPath = enforcement && entries.some((e) => e['instance-path']);
	const cols = ['ID', 'Title', ...(withStatus ? ['Status'] : []), ...(withEnforcer ? ['Held by'] : []), ...(withApplies ? ['Binds'] : []), ...(withPath ? ['Lives at'] : []), 'Hydrate when'];
	const head = [`| ${cols.join(' | ')} |`, `|${cols.map(() => '---').join('|')}|`];
	const rows = entries.map((e) => {
		const href = linkFrom ? path.relative(linkFrom, e.rel) : e.rel;
		const cells = [`[${e.id}](${href})`, cell(e.title)];
		if (withStatus) cells.push(cell(e.status));
		if (withEnforcer) cells.push(e['enforced-by'] ? `\`${cell(e['enforced-by'])}\`` : (/0$/.test(e.id) ? '' : 'reading'));
		if (withApplies) cells.push(e['applies-to'] ? cell(String(e['applies-to']).replace(/[[\]]/g, '')) : '');
		if (withPath) cells.push(e['instance-path'] ? String(e['instance-path']).replace(/[[\]]/g, '').split(',').map((x) => `\`${x.trim()}\``).join(', ') : '');
		cells.push(cell(e['hydrate-when']));
		return `| ${cells.join(' | ')} |`;
	});
	return [...head, ...rows].join('\n');
}

// One section per layer, charter first because its id ends in 0. There is no Category column: the
// heading states the layer once per layer instead of once per entry, and each row's link already
// names the directory. `layer`, `category` and `prefix` are distinct - see E2.
function ledgerSections(entries) {
	return LAYERS
		.map((dir) => [dir, ordered(entries.filter((e) => e.dir === dir))])
		.filter(([, es]) => es.length)
		.map(([dir, es]) => `## ${headingOf(dir)}\n\n${table(es, null)}`)
		.join('\n\n---\n\n');
}

function categoryTable(entries, dir) {
	return table(ordered(entries.filter((e) => e.dir === dir)), dir, { enforcement: true });
}

// Replace the delimited region, or report that the file does not opt in.
function splice(file, table) {
	const abs = path.join(ROOT, file);
	if (!existsSync(abs)) return null;
	const text = readFileSync(abs, 'utf8');
	const b = text.indexOf(BEGIN);
	const e = text.indexOf(END);
	if (b === -1 || e === -1) return { file, opted: false, text, next: text };
	const next = text.slice(0, b) + BEGIN + '\n' + table + '\n' + text.slice(e);
	return { file, opted: true, text, next };
}

// An id addresses an entry, so two entries holding one id means the corpus cannot address either.
// Nothing downstream notices: the ledger renders both rows, every `related:` edge naming the id
// becomes ambiguous, and check-entry-body keys its exemptIds on (category, id), so exempting one
// of the pair silently exempts the other and a gate stops gating. Refuse to emit, for the same
// reason an empty index is refused: an artifact that encodes the defect is worse than none.
function collisions(entries) {
	const byId = new Map();
	for (const e of entries) byId.set(e.id, [...(byId.get(e.id) ?? []), e.rel]);
	return [...byId].filter(([, files]) => files.length > 1);
}

const check = process.argv.includes('--check');
const entries = collect();
if (!entries.length) { console.error('FAIL  no entries found; refusing to write an empty index'); process.exit(1); }

const duplicated = collisions(entries);
if (duplicated.length) {
	for (const [id, files] of duplicated) console.error(`FAIL  duplicate id  ${id} is declared by ${files.join(' and ')}`);
	console.error(`\n${duplicated.length} duplicate id(s); refusing to index a corpus that cannot address its own entries.`);
	process.exit(1);
}

// A citation that resolves to nothing is worse than an absent one, because it reads as routing.
// Nothing else reports these: skill-graph resolves `prerequisite` and `composes` between SKILL.md
// bodies and never reads catalogue frontmatter, and the schema validates one file at a time, so a
// cross-file reference is outside what any single-file contract can see. Checked here because
// collect() is already the only inventory of which ids exist. Blocking is not onerous: the root
// charter already requires a retired entry's pointers to be repaired in the same commit.
// supersedes is not here: it names retired ids, which by design are not entries, and
// check-id-reuse holds it to naming ids that history shows retired.
const EDGE_FIELDS = ['related', 'related-axioms', 'methods', 'produces'];
function danglingEdges(entries) {
	const known = new Set(entries.map((e) => e.id));
	const out = [];
	for (const e of entries)
		for (const field of EDGE_FIELDS)
			for (const target of String(e[field] ?? '').replace(/[[\]]/g, '').split(',').map((s) => s.trim()).filter(Boolean))
				if (!known.has(target)) out.push({ rel: e.rel, field, target });
	return out;
}

const dangling = danglingEdges(entries);
if (dangling.length) {
	for (const d of dangling) console.error(`FAIL  dangling edge  ${d.rel}: ${d.field} names ${d.target}, which is not an entry`);
	console.error(`\n${dangling.length} dangling edge(s); refusing to index a corpus whose own citations do not resolve.`);
	process.exit(1);
}

// Every layer must have a charter, and the charter's title must begin with the layer's own name.
// The charter is what makes a layer self-describing: its id carries the prefix, its title the
// heading, its trigger the route in. A layer without one cannot be discovered from its directory,
// and a charter titled out of step with its directory silently renames the section.
function headingDisagreements(entries) {
	const out = [];
	for (const dir of LAYERS) {
		const charter = entries.find((e) => e.rel === `${dir}/README.md`);
		if (!charter) { out.push(`${dir}/ has no charter; ${dir}/README.md must declare an id and a category`); continue; }
		const first = String(charter.title).split(' - ')[0].trim();
		if (first !== headingOf(dir))
			out.push(`${dir}/README.md is titled "${first} - ...", so its heading would read "${first}" rather than "${headingOf(dir)}"`);
	}
	return out;
}


const headingProblems = headingDisagreements(entries);
if (headingProblems.length) {
	for (const p of headingProblems) console.error(`FAIL  charter  ${p}`);
	console.error(`\n${headingProblems.length} charter problem(s); a layer's heading is derived from it, so it must agree.`);
	process.exit(1);
}

// An entry's category must match the layer that owns it. The value is the entry's own claim about
// where it lives, and the two can disagree: an entry sitting in patterns/ while declaring
// `category: methodology` passed every gate before this existed. Nothing else can catch it.
// check-entry-body reads the declared category deliberately, so a misfiled entry is held to the
// wrong shape rather than reported, and only four of thirteen categories are body-governed, so the
// other nine misfile in silence. The ledger stopped rendering the value once the layer moved to the
// section heading, which removed the last place a human might have noticed.
function misfiled(entries) {
	const out = [];
	for (const dir of LAYERS) {
		const charter = entries.find((e) => e.rel === `${dir}/README.md`);
		if (!charter) continue; // headingDisagreements already reports a layer with no charter
		for (const e of entries.filter((x) => x.dir === dir && x.category !== charter.category))
			out.push({ rel: e.rel, declared: e.category, expected: charter.category });
	}
	return out;
}

const wrongLayer = misfiled(entries);
if (wrongLayer.length) {
	for (const w of wrongLayer)
		console.error(`FAIL  misfiled  ${w.rel} declares category '${w.declared}', but its layer's charter declares '${w.expected}'`);
	console.error(`\n${wrongLayer.length} misfiled entr(ies); an entry's category names the layer that owns it.`);
	process.exit(1);
}


// A spanning set declares its members in its charter. Each must exist and be active: a set that
// gathers a superseded or draft entry routes a reader to guidance no longer, or not yet, in force.
const listOf = (v) => String(v ?? '').replace(/[[\]]/g, '').split(',').map((s) => s.trim()).filter(Boolean);
const byIdAll = new Map(entries.map((e) => [e.id, e]));
const setProblems = [];
for (const e of entries.filter((x) => x.category === 'set' && !/^ST0$/.test(x.id))) {
	const members = listOf(e.members);
	if (!members.length) setProblems.push(`${e.rel}: a set with no members`);
	for (const id of members) {
		const m = byIdAll.get(id);
		if (!m) setProblems.push(`${e.rel}: member ${id} is not an entry`);
		else if (m.status !== 'active') setProblems.push(`${e.rel}: member ${id} is ${m.status}, not active`);
	}
}
for (const e of entries.filter((x) => x.members !== undefined && x.category !== 'set')) setProblems.push(`${e.rel}: members is declared on a ${e.category}, not a set`);
if (setProblems.length) {
	for (const p of setProblems) console.error(`FAIL  set  ${p}`);
	console.error(`\n${setProblems.length} set problem(s); a set may gather only active entries that exist.`);
	process.exit(1);
}

const targets = [['INDEX.md', ledgerSections(entries)]];
// Each domain entry carries the work-types that act on it, generated from the work-types' own
// domainEligibility - the list that governs. A hand-kept copy on the domain disagreed with the
// work-types in 23 places and was consulted by nothing; generating it makes disagreement impossible.
for (const d of entries.filter((x) => x.category === 'domain' && /^D[1-9][0-9]*$/.test(x.id))) {
	const slug = String(d.title).split(' - ')[0].trim();
	const acting = entries.filter((w) => w.category === 'work-type' && /^W[1-9][0-9]*$/.test(w.id) && listOf(w.domainEligibility).includes(slug));
	targets.push([d.rel, table(ordered(acting), path.dirname(d.rel))]);
}
// Each trait entry carries the axioms it brings into force, generated from the axioms' applies-to -
// the only field that decides binding. A hand-kept copy on the trait was a second declaration of
// one relationship, checked by nothing; readers found it and could not tell which governed.
for (const t of entries.filter((x) => x.category === 'trait' && /^T[1-9][0-9]*$/.test(x.id))) {
	const slug = String(t.title).split(' - ')[0].trim();
	const binding = entries.filter((a) => a.category === 'axiom' && /^A[1-9][0-9]*$/.test(a.id) && listOf(a['applies-to']).includes(slug));
	targets.push([t.rel, table(ordered(binding), path.dirname(t.rel))]);
}
// Each artifact type carries the work-types that produce it, generated from their produces field -
// the side whose meaning includes the relation. Generated into the type's own file.
for (const t of entries.filter((x) => x.category === 'artifact' && /^AR[1-9][0-9]*$/.test(x.id))) {
	const by = entries.filter((w) => w.category === 'work-type' && listOf(w.produces).includes(t.id));
	targets.push([t.rel, table(ordered(by), path.dirname(t.rel))]);
}
// Each spanning set's own file carries a generated table of its members, from its members list.
for (const e of entries.filter((x) => x.category === 'set' && !/^ST0$/.test(x.id)))
	targets.push([e.rel, table(ordered(listOf(e.members).map((id) => byIdAll.get(id))), path.dirname(e.rel))]);
for (const dir of LAYERS) {
	const readme = `${dir}/README.md`;
	if (existsSync(path.join(ROOT, readme))) targets.push([readme, categoryTable(entries, dir)]);
}

let stale = 0, written = 0, skipped = 0;
for (const [file, table] of targets) {
	const r = splice(file, table);
	if (!r) continue;
	if (!r.opted) { skipped++; continue; }
	if (r.text === r.next) continue;
	if (check) { console.log(`FAIL  stale  ${file}`); stale++; }
	else { writeFileSync(path.join(ROOT, file), r.next); console.log(`wrote  ${file}`); written++; }
}

console.log();
console.log(`${entries.length} entries, ${targets.length - skipped} generated region(s), ${skipped} file(s) without markers.`);
if (check && stale) { console.log(`${stale} region(s) out of date. Run tools/generate-index.mjs.`); process.exit(1); }
if (check) console.log('all generated regions are current.');

#!/usr/bin/env node
// s6-one-sentence-per-line - enforce S6: each sentence on its own line, breaks made visible.
//
// Sovereign duty: this rule and no other, and it owns BOTH halves of it. The check and the fix
// share one definition of a sentence boundary, which is the point: that definition previously
// existed four times in three languages and the copies disagreed twice in one day. A line
// containing "e.g." was reportable by the checker and unfixable by the converter, which makes a
// gate unsatisfiable rather than merely noisy.
//
// A file passes S6 exactly when this tool has nothing to change. That is the definition of
// compliance, not an approximation of it.
//
//   --check   report the lines a fix would rewrite, and exit non-zero if any (the default)
//   --fix     rewrite them
//
// Prose only. Frontmatter, fenced blocks, tables, headings, list items and blockquotes are
// copied through untouched, because S6 names "a list wearing prose - a real markdown list" as
// the correct outcome. Inline code is masked before splitting, so a hard break is never written
// into a reader's command.
//
// Usage:  tools/s6-one-sentence-per-line.mjs [--check|--fix] FILE...
import { readFileSync, writeFileSync } from 'node:fs';

// The leading boundary is load-bearing: without it "St." matches the tail of "rest.",
// "al." the tail of "final.", and the splitter silently declines to split real sentences.
const ABBREV = /(?:^|[\s("'[])(?:e\.g|i\.e|etc|vs|cf|approx|Dr|Mr|Ms|St|No|Fig|Eq|Sec|al)\.$/i;

// Split a joined paragraph into sentences without breaking on abbreviations or initials.
function splitSentences(text) {
	const parts = [];
	let start = 0;
	for (let i = 0; i < text.length; i++) {
		if (!'.!?'.includes(text[i])) continue;
		// an ellipsis is not a sentence end
		if (text.slice(i, i + 3) === '...') { i += 2; continue; }
		if (text[i - 1] === '.' || text[i + 1] === '.') continue;
		// A terminator may be followed by closing delimiters before the space: a quote, a bold
		// marker, a bracket. Requiring the space immediately after the terminator missed
		// `truths." A sovereign backplane` and every `**...act.** A field` in the corpus.
		const rest = text.slice(i + 1);
		const m = rest.match(/^["'*`\)\]]*\s+(?=[A-Z`\[(*_"'\u0001])/);
		if (!m) continue;
		const closers = (m[0].match(/^["'*`\)\]]*/) || [''])[0];
		const head = text.slice(start, i + 1 + closers.length);
		if (ABBREV.test(head)) continue;
		if (/(?:^|\s)[A-Z]\.$/.test(head)) continue; // an initial, e.g. "J."
		parts.push(head.trim());
		start = i + 1 + m[0].length;
	}
	const tail = text.slice(start).trim();
	if (tail) parts.push(tail);
	return parts.filter(Boolean);
}


// Inline code is not prose. A sentence break inside a code span would put a hard-break marker
// into the reader's command, and a span may legitimately contain ". " without ending a sentence.
// Mask spans to opaque tokens carrying no sentence-ending punctuation, then restore them.
function maskInlineCode(text) {
	const spans = [];
	const masked = text.replace(/(`+)([^`]|[^`][\s\S]*?)\1/g, (m) => {
		spans.push(m);
		return `\u0001${spans.length - 1}\u0001`;
	});
	return { masked, spans };
}
function restoreInlineCode(text, spans) {
	return text.replace(/\u0001(\d+)\u0001/g, (_, i) => spans[Number(i)]);
}

function isStructural(line) {
	return (
		line.trim() === '' ||
		/^\s*(#{1,6})\s/.test(line) ||       // heading
		/^\s*\|/.test(line) ||                // table
		/^\s*>/.test(line) ||                 // blockquote
		/^\s*[-*+]\s/.test(line) ||           // bullet
		/^\s*\d+\.\s/.test(line) ||           // ordered item
		/^\s{2,}\S/.test(line) ||             // indented continuation (list body)
		/^---$/.test(line) ||                 // horizontal rule
		/^<!--/.test(line) ||                 // html comment / marker
		/^\s*`{3,}/.test(line) ||             // fence
		/^\s*\*\*[^*]+:\*\*/.test(line)       // metadata line - see below
	);
}
// The metadata line is a `**Key:** value` header block, and it is not prose. S6 calls it
// "coupled, each needing its own rendered line"; joining a run of them produces the single
// rendered block the rule exists to prevent. The join was also unrecoverable: with no sentence
// terminator between a key's value and the next "**Key:**", the splitter could not undo it, and
// the tool then reported the damaged file clean - a fix that certifies its own corruption.
//
// The colon must sit INSIDE the bold span. That is what separates a metadata key from a bold
// sentence opener like "**Diffs.** Rewording one sentence...", which is prose and must still
// split. Both cases are held by tools/s6-one-sentence-per-line.test.sh.

function reflow(src) {
	const lines = src.split('\n');
	const out = [];
	let i = 0;

	// copy YAML frontmatter verbatim
	if (lines[0] === '---') {
		out.push(lines[i++]);
		while (i < lines.length && lines[i] !== '---') out.push(lines[i++]);
		if (i < lines.length) out.push(lines[i++]);
	}

	let fence = null;
	while (i < lines.length) {
		const line = lines[i];
		const fenceMatch = line.match(/^\s*(`{3,})/);
		if (fenceMatch) {
			if (fence === null) fence = fenceMatch[1].length;
			else if (fenceMatch[1].length >= fence) fence = null;
			out.push(line);
			i++;
			continue;
		}
		if (fence !== null || isStructural(line)) { out.push(line); i++; continue; }

		// gather one prose paragraph
		const buf = [];
		while (i < lines.length && !isStructural(lines[i]) && !/^\s*`{3,}/.test(lines[i])) {
			buf.push(lines[i].replace(/\\$/, '').trim());
			i++;
		}
		const { masked, spans } = maskInlineCode(buf.join(' '));
		const sentences = splitSentences(masked).map((s) => restoreInlineCode(s, spans));
		sentences.forEach((s, n) => out.push(n < sentences.length - 1 ? `${s}\\` : s));
	}
	return out.join('\n');
}

const args = process.argv.slice(2);
// Check unless told to fix. The default once rewrote files when a reader ran it to inspect them, and
// a stash of pending work could not be restored over the result. A tool that changes files on its
// default path surprises whoever runs it to look.
const check = !args.includes('--fix');
const files = args.filter((a) => !a.startsWith('--'));
if (!files.length) { console.error('usage: s6-one-sentence-per-line.mjs [--check|--fix] FILE...'); process.exit(2); }

// The same exemption markers every style checker honours.
function exempt(text) {
	if (/style-check: allow S6/.test(text)) return true;
	return text.split('\n').slice(0, 12).some((l) => l.includes('GENERATED FILE'));
}

let failures = 0, rewritten = 0;
for (const f of files) {
	const before = readFileSync(f, 'utf8');
	if (exempt(before)) continue;
	const after = reflow(before);
	if (before === after) continue;
	if (check) {
		// Report the first line at which the two diverge, which is where the fix would start.
		const a = before.split('\n'), b = after.split('\n');
		let i = 0;
		while (i < a.length && i < b.length && a[i] === b[i]) i++;
		console.log(`FAIL  S6   ${f}:${i + 1}  sentence layout differs from S6; run --fix`);
		failures++;
	} else {
		writeFileSync(f, after);
		rewritten++;
	}
}

console.log();
if (check) {
	if (failures) { console.log(`${failures} S6 failure(s) across ${files.length} file(s).`); process.exit(1); }
	console.log(`clean: ${files.length} file(s), rule S6.`);
} else {
	console.log(`s6: rewrote ${rewritten} of ${files.length} file(s).`);
}

#!/usr/bin/env bash
# s13-plain-ascii - enforce S13: printable ASCII only, Box Drawing excepted.
#
# Sovereign duty: this rule and no other. The conversion table it applies in --fix is the one
# style/S13-plain-ascii-in-markdown.md publishes, so the rule has one definition and the checker
# and the converter cannot disagree about it.
#
# Usage:  tools/s13-plain-ascii.sh [--fix] [FILE ...]

set -uo pipefail
root=$(cd "$(dirname "$0")/.." && pwd)
. "$root/tools/lib/style-common.sh"

fix=0; args=()
while [ $# -gt 0 ]; do case "$1" in --fix) fix=1; shift ;; *) args+=("$1"); shift ;; esac; done
mapfile -t files < <(style_files "$root" "${args[@]+"${args[@]}"}")

for f in "${files[@]}"; do
	[ -f "$f" ] || continue
	style_exempt "$f" S13 && continue
	if [ "$fix" -eq 1 ]; then
		perl -CSD -i -pe '
			s/ \x{2014} / - /g; s/\x{2014}/-/g; s/\x{2013}/-/g; s/\x{2212}/-/g;
			s/\x{2192}/->/g; s/\x{2190}/<-/g; s/\x{2194}/<->/g; s/\x{27F6}/-->/g;
			s/\x{21D2}/=>/g; s/\x{27FA}/<=>/g;
			s/\x{2265}/>=/g; s/\x{2264}/<=/g; s/\x{2260}/!=/g; s/\x{2248}/~=/g;
			s/\x{00D7}/x/g; s/\x{00B1}/+\/-/g; s/\x{2026}/.../g;
			s/\x{2019}/\x27/g; s/[\x{201C}\x{201D}]/"/g;
			s/ \x{00B7} / - /g; s/\x{00B7}/-/g;
			s/\x{00A9}/(c)/g;
			# A word-substitution keeps the separating space only when a word follows it.
			# Emitting it unconditionally turns "\x{00A7}-style" into "section -style", inventing a
			# space the author did not write.
			s/\x{00A7}\s*(?=\w)/section /g;   s/\x{00A7}\s*/section/g;
			s/\x{25B6}\s*(?=\w)/> /g;         s/\x{25B6}\s*/>/g;
			s/\x{25C9}\s*(?=\w)/* /g;         s/\x{25C9}\s*/*/g;
			s/\x{26A0}\s*(?=\w)/WARNING /g;   s/\x{26A0}\s*/WARNING/g;
			s/\x{2705}\s*(?=\w)/[x] /g;       s/\x{2705}\s*/[x]/g;
			s/\x{2713}\s*(?=\w)/[x] /g;       s/\x{2713}\s*/[x]/g;
			s/\x{2717}\s*(?=\w)/[ ] /g;       s/\x{2717}\s*/[ ]/g;
			s/\x{27F3}\s*(?=\w)/retry /g;     s/\x{27F3}\s*/retry/g;
			s/\x{1F534}\s*//g; s/\x{1F916}\s*//g;
		' "$f"
		continue
	fi
	while IFS= read -r line; do
		[ -n "$line" ] && style_report S13 "$f" "$line" "non-ASCII character"
	done < <(grep -nP '[\x{80}-\x{24FF}\x{2580}-\x{10FFFF}]' "$f" | cut -d: -f1 | uniq)
done

[ "$fix" -eq 1 ] && { echo; echo "s13: applied to ${#files[@]} file(s)."; exit 0; }
style_summary S13 "${#files[@]}"

#!/usr/bin/env bash
# s10-section-rules - enforce S10: a horizontal rule between top-level sections.
#
# Sovereign duty: this rule and no other. Two responsibilities that read as one: a document past
# the size threshold needs a rule between each pair of sections, and no document may carry two
# rules in a row, because a count-based check passes a duplicate and one did.
#
# Usage:  tools/s10-section-rules.sh [--fix] [FILE ...]

set -uo pipefail
root=$(cd "$(dirname "$0")/.." && pwd)
. "$root/tools/lib/style-common.sh"

fix=0; args=()
while [ $# -gt 0 ]; do case "$1" in --fix) fix=1; shift ;; *) args+=("$1"); shift ;; esac; done
mapfile -t files < <(style_files "$root" "${args[@]+"${args[@]}"}")

for f in "${files[@]}"; do
	[ -f "$f" ] || continue
	style_exempt "$f" S10 && continue

	if [ "$fix" -eq 1 ]; then
		# Insert only where none exists, so a second pass adds nothing.
		perl -0777 -i -pe '
			my @out; my $fence = 0; my $seen = 0;
			for my $line (split /^/, $_) {
				$fence = !$fence if $line =~ /^`{3,}/;
				if (!$fence && $line =~ /^## / && $seen++) {
					my $i = $#out; $i-- while $i >= 0 && $out[$i] =~ /^\s*$/;
					unless ($i >= 0 && $out[$i] =~ /^---\s*$/) {
						pop @out while (@out && $out[-1] =~ /^\s*$/);
						push @out, "\n", "---\n", "\n";
					}
				}
				push @out, $line;
			}
			$_ = join "", @out;
		' "$f"
		continue
	fi

	# A rule separates two sections; two in a row separates nothing.
	while IFS= read -r dup; do
		[ -n "$dup" ] && style_report S10 "$f" "$dup" "two horizontal rules in a row"
	done < <(awk '/^`{3,}/{c=!c} c{next}
	              /^---[[:space:]]*$/{ if (seen && blanks) print FNR; seen=1; blanks=1; next }
	              /^[[:space:]]*$/{next} {blanks=0}' "$f")

	h2=$(awk '/^`{3,}/{c=!c; next} !c && /^## /{n++} END{print n+0}' "$f")
	[ "$h2" -lt 5 ] && continue
	hr=$(awk 'FNR==1 && /^---$/ {fm=1; next} fm && /^---$/ {fm=0; next} /^`{3,}/{c=!c} !c && /^---$/{n++} END{print n+0}' "$f")
	need=$((h2 - 1))
	[ "$hr" -ge "$need" ] || style_report S10 "$f" 1 "$h2 H2 sections but $hr horizontal rules; need $need"
done

[ "$fix" -eq 1 ] && { echo; echo "s10: applied to ${#files[@]} file(s)."; exit 0; }
style_summary S10 "${#files[@]}"

#!/usr/bin/env node
// check-decisions - hold the decision register to the shape AR4 requires of it.
//
// Sovereign duty: the register's own integrity and no other. A ruling is changed only by a later
// row, so the register is only trustworthy if every row can be addressed, ordered and traced.
//
//   every id is four digits, unique, and in ascending order
//   every row has a kind (general | project), an authority, and a status
//   a status is ratified, proposed, or "superseded by <id>" naming a later row
//   every lineage reference (supersedes / amends) names an earlier row
//   a general row names entries in affects, and every named path exists
//   a project row names none
//   absorbed is yes | pending | contested for general rows, and - for project rows
//
// Whether an entry actually states its ruling is read, not checked: registration in an index is
// not absorption (AR4), and a script matching words would report the cheaper reading as the real one.
//
// Exit non-zero on any defect. Reports pending and contested rows without failing.
//
// Usage:  node tools/check-decisions.mjs [docs/DECISIONS.md]

import { readFileSync, existsSync } from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const file = path.join(ROOT, process.argv[2] || 'docs/DECISIONS.md');
if (!existsSync(file)) { console.log(`FAIL  missing  ${file}`); process.exit(1); }

const rows = readFileSync(file, 'utf8').split('\n')
	.filter((l) => /^\| \d{4} \|/.test(l))
	.map((l) => l.slice(1, -1).split(' | ').map((c) => c.trim()));

let fail = 0;
const bad = (id, msg) => { console.log(`FAIL  ${id}  ${msg}`); fail++; };
const ids = rows.map((r) => r[0]);
const pending = [], contested = [];

rows.forEach((r, i) => {
	const [id, date, ruling, kind, authority, status, lineage, affects, absorbed] = r;
	if (r.length !== 9) return bad(id, `has ${r.length} columns, expected 9`);
	if (ids.indexOf(id) !== i) bad(id, 'id is not unique');
	if (i > 0 && id <= ids[i - 1]) bad(id, 'id is out of order');
	if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) bad(id, 'date is not YYYY-MM-DD');
	if (!ruling) bad(id, 'ruling is empty');
	if (!authority || authority === '-') bad(id, 'authority names no one');
	if (!['general', 'project'].includes(kind)) bad(id, `kind '${kind}' is not general or project`);
	const sup = /^superseded by (\d{4})$/.exec(status);
	if (!['ratified', 'proposed'].includes(status) && !sup) bad(id, `status '${status}' is not ratified, proposed or superseded by <id>`);
	if (sup && !(ids.includes(sup[1]) && sup[1] > id)) bad(id, `superseded by ${sup[1]}, which is not a later row`);
	if (lineage !== '-') {
		const m = /^(supersedes|amends) ([\d, ]+)$/.exec(lineage);
		if (!m) bad(id, `lineage '${lineage}' is not 'supersedes|amends <ids>'`);
		else for (const ref of m[2].split(',').map((s) => s.trim())) if (!(ids.includes(ref) && ref < id)) bad(id, `lineage names ${ref}, which is not an earlier row`);
	}
	if (kind === 'general') {
		const paths = [...affects.matchAll(/`([^`]+)`/g)].map((m) => m[1]);
		if (!paths.length) bad(id, 'a general ruling names no entry in affects');
		for (const p of paths) if (!existsSync(path.join(ROOT, p))) bad(id, `affects names ${p}, which does not exist`);
		if (!['yes', 'pending', 'contested'].includes(absorbed)) bad(id, `absorbed '${absorbed}' is not yes, pending or contested`);
		if (absorbed === 'pending') pending.push(id);
		if (absorbed === 'contested') contested.push(id);
	} else if (kind === 'project') {
		if (affects !== '-') bad(id, 'a project decision names entries in affects');
		if (absorbed !== '-') bad(id, 'a project decision has an absorbed value');
	}
});

console.log(`${rows.length} rulings; ${rows.filter((r) => r[3] === 'general').length} general, ${rows.filter((r) => r[3] === 'project').length} project.`);
if (pending.length) console.log(`pending absorption: ${pending.join(', ')}`);
if (contested.length) console.log(`contested: ${contested.join(', ')}`);
if (fail) { console.log(`${fail} register defect(s).`); process.exit(1); }
console.log('the register is well formed.');

