#!/usr/bin/env node
//
// The applies-to vocabulary and the traits layer name the same things.
//
// An axiom's applies-to field is constrained to an enum in the catalogue contract, so a
// misspelled or undefined tag is refused rather than silently binding nothing. The enum is a
// second list of the traits declared in traits/, and two lists of one thing drift: add a trait
// and forget the enum, and every axiom tagged with it is refused; remove one and the enum keeps
// admitting a tag nothing defines.
//
// This check makes the two one fact. The enum must equal the declared traits plus the floor,
// any-system, which is a valid value and deliberately not a trait.
//
// Usage:  node tools/check-traits.mjs

import { readFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const FLOOR = "any-system";

const schema = JSON.parse(readFileSync(join(root, "schemas/catalog-entry/v1alpha1/catalog-entry.schema.json"), "utf8"));
const enumValues = new Set(schema.properties["applies-to"]?.items?.enum ?? []);

// A trait's tag is the slug after its id in the filename, which is also the title's leading word.
const declared = new Set(
	readdirSync(join(root, "traits"))
		.filter((f) => /^T[1-9]\d*-.+\.md$/.test(f))
		.map((f) => f.replace(/^T\d+-/, "").replace(/\.md$/, "")),
);

const failures = [];
for (const t of declared) if (!enumValues.has(t)) failures.push(`FAIL  trait ${t} is declared in traits/ and absent from the applies-to enum`);
for (const v of enumValues) if (v !== FLOOR && !declared.has(v)) failures.push(`FAIL  applies-to admits ${v}, which no trait in traits/ defines`);
if (!enumValues.has(FLOOR)) failures.push(`FAIL  applies-to no longer admits the floor, ${FLOOR}`);

if (failures.length) {
	for (const f of failures) console.log(f);
	console.log(`\n${failures.length} failure(s): the applies-to vocabulary and the traits layer disagree.`);
	process.exit(1);
}
console.log(`clean: ${declared.size} trait(s) and the floor match the applies-to vocabulary exactly.`);

#!/usr/bin/env node
//
// The board and the backlog agree with each other.
//
// docs/BOARD.md is the plan - mutable, reorderable, short. docs/BACKLOG.md is the record -
// append-and-close, nothing deleted. The board states a five-rule contract binding the two, and
// until this script existed every rule was prose that nothing checked.
//
// That was not hypothetical. Within two commits of the board being written it carried a milestone
// out of plan order, a finding arguing that a closed row was still open, and an item citing no row
// at all - and that item was the one whose duty was to mechanise this contract. A person found all
// three by asking. A script finds them on every change.
//
// What it checks, and the defect each catches:
//
//   R1  every board item cites a backlog row          an orphaned plan item
//   R2  every cited row exists                        a citation to nothing
//   R3  every row carries impact and principle scores  a row the generated views cannot order
//   R7  the ledger and held list match the record      a hand copy drifting from the scores
//   R4  no closed row is planned in an open milestone the record and the plan disagreeing
//   R5  milestones appear in ascending order          an accidental priority nobody chose
//   R6  a DONE milestone cites no open row            a milestone claiming more than it delivered
//
// It reads both files as written rather than a separate declaration, because the files ARE the
// declaration; a second copy of the board's structure would be the drift this exists to prevent.
//
// Usage:  node tools/check-board.mjs

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const boardPath = join(root, "docs/BOARD.md");
const backlogPath = join(root, "docs/BACKLOG.md");

// A corpus with no board has nothing to reconcile. Absence is not a failure here; it is the
// bootstrap state, and a check that refused it would block the commit that creates the board.
if (!existsSync(boardPath) || !existsSync(backlogPath)) {
	console.log("clean: no board and backlog pair to reconcile.");
	process.exit(0);
}

const board = readFileSync(boardPath, "utf8");
const backlog = readFileSync(backlogPath, "utf8");

const failures = [];
const fail = (rule, msg) => failures.push(`FAIL  ${rule}  ${msg}`);

// --- the record -------------------------------------------------------------------------------

// A backlog row is a table row whose first cell is a bolded B-id. CLOSED anywhere in it marks the
// disposition; everything else is open. Parked and Retired sections hold rows of the same shape.
// Columns: id | impact | principle | finding | evidence | state. The scores are declared once, on
// the row; the board's ledger and held list are generated from them, so the two cannot disagree.
const cellsOf = (line) => line.replace(/^\|\s*/, "").replace(/\s*\|\s*$/, "").split(/\s+(?<!\\)\|\s+/);
const rows = new Map();
for (const line of backlog.split("\n")) {
	const m = line.match(/^\|\s*\*\*(B\d+)\*\*\s*\|/);
	if (!m) continue;
	const c = cellsOf(line);
	const title = (c[3] || "").match(/\*\*(.+?)\*\*/);
	rows.set(m[1], {
		closed: /\bCLOSED\b/.test(line),
		impact: c[1], principle: c[2],
		title: title ? title[1] : (c[3] || "").slice(0, 120),
		state: c[c.length - 1] || "",
	});
}

// --- the plan ---------------------------------------------------------------------------------

// Walk the board once, tracking which milestone we are inside and whether we are in Held, so an
// item row is attributed to the milestone heading above it.
const items = [];
const milestones = [];
const held = new Set();
let current = null;
let inHeld = false;

for (const line of board.split("\n")) {
	const h = line.match(/^##\s+(M(\d+))\b.*?`([A-Z]+)`/);
	if (h) {
		current = { id: h[1], n: Number(h[2]), status: h[3] };
		milestones.push(current);
		inHeld = false;
		continue;
	}
	if (/^##\s+Held\b/.test(line)) {
		current = null;
		inHeld = true;
		continue;
	}
	if (/^##\s/.test(line)) {
		current = null;
		inHeld = false;
		continue;
	}

	if (inHeld) {
		const m = line.match(/^\|\s*\*\*(B\d+)\*\*\s*\|/);
		if (m) held.add(m[1]);
		continue;
	}

	const it = line.match(/^\|\s*(M\d+\.\d+[a-z]?)\s*\|/);
	if (it && current) {
		const cited = [...line.matchAll(/`(B\d+)`/g)].map((x) => x[1]);
		items.push({ id: it[1], milestone: current, cited });
	}
}

// --- R1, R2: every item cites, and every citation resolves ------------------------------------

for (const item of items) {
	if (item.cited.length === 0) {
		fail("R1", `${item.id} cites no backlog row`);
		continue;
	}
	for (const b of item.cited) {
		if (!rows.has(b)) fail("R2", `${item.id} cites ${b}, which is not a backlog row`);
	}
}

// --- R3: every open row is planned or held - held is derived, not listed by hand --------------
//
// A row is planned when a live item in an open milestone cites it, and held otherwise. Holding is
// therefore a fact read from the plan, and the held list is generated; R3 now checks that every row
// carries the scores the generated views order by.

const itemLine = (id) => board.split("\n").find((l) => l.startsWith(`| ${id} `)) ?? "";
const plannedIn = new Map();
for (const item of items) {
	if (item.milestone.status === "DONE" || /`DONE`/.test(itemLine(item.id))) continue;
	for (const b of item.cited) if (!plannedIn.has(b)) plannedIn.set(b, item.id);
}
for (const [b, r] of rows) {
	if (!/^S[1-5]$/.test(r.impact ?? "")) fail("R3", `${b} has impact '${r.impact}', not S1-S5`);
	if (!/^A\d+ (mandate|signal)( - A\d+)?$/.test(r.principle ?? "")) fail("R3", `${b} has principle '${r.principle}', not 'A<n> mandate|signal' with an optional secondary axiom`);
}

// --- R4: a closed row is not planned as live work ---------------------------------------------

for (const item of items) {
	if (item.milestone.status === "DONE") continue;
	for (const b of item.cited) {
		if (rows.get(b)?.closed && !/`DONE`/.test(board.split("\n").find((l) => l.startsWith(`| ${item.id} `)) ?? "")) {
			fail("R4", `${item.id} in ${item.milestone.id} (${item.milestone.status}) plans ${b}, which is CLOSED`);
		}
	}
}

// --- R5: document order is plan order ---------------------------------------------------------

for (let i = 1; i < milestones.length; i++) {
	if (milestones[i].n < milestones[i - 1].n) {
		fail("R5", `${milestones[i].id} appears after ${milestones[i - 1].id}; the board's order is its plan`);
	}
}

// --- R6: a finished milestone delivered what it cites -----------------------------------------

for (const item of items) {
	if (item.milestone.status !== "DONE") continue;
	for (const b of item.cited) {
		const r = rows.get(b);
		// A DONE milestone may legitimately leave a row open when the row's remaining work moved to
		// another milestone; that is only lawful if the row is still planned somewhere live.
		if (r && !r.closed) {
			const elsewhere = items.some((o) => o.milestone.status !== "DONE" && o.cited.includes(b));
			if (!elsewhere) fail("R6", `${item.id} sits in DONE ${item.milestone.id} but ${b} is still open and planned nowhere else`);
		}
	}
}

// --- R7: the ledger and the held list are generated from the record ---------------------------
//
// Order is on the higher of the two scores, never a blend: a mandate breach ranks as S2 and an
// enforcement signal as S4, ties go to the mandate, then to impact. Run with --write to regenerate.

const rank = (r) => {
	const imp = Number(r.impact.slice(1));
	const pr = /mandate/.test(r.principle) ? 2 : 4;
	return [Math.min(imp, pr), /mandate/.test(r.principle) ? 0 : 1, imp];
};
const cmp = (a, b) => { const x = rank(a[1]), y = rank(b[1]); for (let i = 0; i < 3; i++) if (x[i] !== y[i]) return x[i] - y[i]; return Number(a[0].slice(1)) - Number(b[0].slice(1)); };
const open = [...rows].filter(([, r]) => !r.closed && /^S[1-5]$/.test(r.impact ?? "") && /^A\d+ /.test(r.principle ?? "")).sort(cmp);
const esc = (t) => t.replace(/\|/g, "\\|").trim();
const trigger = (st) => { const m = st.match(/TRIGGER:?\**\s*(.*)$/i); return esc((m ? m[1] : st).replace(/\*\*/g, "")); };
const ledger = ["| Row | Impact | Principle | Planned in | Finding |", "|---|---|---|---|---|",
	...open.map(([b, r]) => `| \`${b}\` | ${r.impact} | ${r.principle} | ${plannedIn.get(b) ?? "held"} | ${esc(r.title)} |`)].join("\n");
const heldRows = open.filter(([b]) => !plannedIn.has(b));
const heldTable = ["| Row | Impact | Principle | Finding | Revival trigger |", "|---|---|---|---|---|",
	...heldRows.map(([b, r]) => `| \`${b}\` | ${r.impact} | ${r.principle} | ${esc(r.title)} | ${trigger(r.state)} |`)].join("\n");

let next = board;
const regions = [["ledger", ledger], ["held", heldTable]];
for (const [name, body] of regions) {
	const B = `<!-- BEGIN GENERATED: ${name}. Run tools/check-board.mjs --write; do not edit by hand. -->`, E = `<!-- END GENERATED: ${name} -->`;
	const i = next.indexOf(B), j = next.indexOf(E);
	if (i === -1 || j === -1) { fail("R7", `docs/BOARD.md has no generated ${name} region`); continue; }
	next = next.slice(0, i) + B + "\n" + body + "\n" + next.slice(j);
}
if (process.argv.includes("--write")) {
	if (next !== board) writeFileSync(boardPath, next);
} else if (next !== board && !failures.some((f) => f.includes("R7"))) {
	fail("R7", "the generated ledger or held list is out of date; run tools/check-board.mjs --write");
}

// --- report -----------------------------------------------------------------------------------

if (failures.length) {
	for (const f of failures) console.log(f);
	console.log(`\n${failures.length} failure(s): the board and the backlog disagree.`);
	process.exit(1);
}

console.log(
	`clean: ${items.length} item(s) across ${milestones.length} milestone(s) reconcile with ${rows.size} backlog row(s); ${heldRows.length} held, generated.`,
);
process.exit(0);

#!/usr/bin/env node
// check-id-reuse - hold that an entry id, once retired, is never issued again.
//
// Sovereign duty: id non-reuse and no other. An id addresses an entry, and frozen records - audits,
// commit messages, closed rows - keep citing it after the entry moves or goes. If the id were
// issued again, every one of those citations would silently point at the wrong entry.
//
// Moved and removed entries leave no stub in the tree, so the list of retired ids is not kept by
// hand: it is derived from git history. An id is retired when a file holding it was deleted, or
// renamed or edited so that it holds a different id. It is reused when a current entry holds a retired id.
// A relocation that keeps its id - a directory renamed - retires nothing.
//
// Exit non-zero if any current entry holds a retired id, or a supersedes value names an id that
// is not retired.
//
// Usage:  tools/check-id-reuse.mjs

import { execFileSync } from 'node:child_process';
import { readFileSync, readdirSync } from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const git = (...args) => execFileSync('git', ['-C', ROOT, ...args], { encoding: 'utf8', maxBuffer: 1 << 28 });

const idOf = (text) => {
	const m = /^---\n([\s\S]*?)\n---/.exec(text || '');
	if (!m) return null;
	const id = /^id:\s*(\S+)\s*$/m.exec(m[1]);
	return id ? id[1] : null;
};
const show = (rev, file) => { try { return git('show', `${rev}:${file}`); } catch { return null; } };
const isEntryPath = (p) => /^[a-z-]+\/[^/]+\.md$/.test(p) && !p.startsWith('docs/');

// Current ids, from every top-level directory's markdown files that declare one.
const current = new Map();
for (const d of readdirSync(ROOT, { withFileTypes: true })) {
	if (!d.isDirectory() || d.name.startsWith('.') || d.name === 'docs' || d.name === 'node_modules') continue;
	for (const f of readdirSync(path.join(ROOT, d.name))) {
		if (!f.endsWith('.md')) continue;
		const id = idOf(readFileSync(path.join(ROOT, d.name, f), 'utf8'));
		if (id) current.set(id, `${d.name}/${f}`);
	}
}

// Retired ids, from history. Renames are detected, so a moved entry appears as R old new. A file
// added in the same commit holding the same id continues the lineage - a split, or a stub left in
// place - so that commit retires nothing for that id.
const retired = new Map();
const log = git('log', '--format=@%H', '--name-status', '-M');
const byCommit = new Map();
let commit = null;
for (const line of log.split('\n')) {
	if (line.startsWith('@')) { commit = line.slice(1); byCommit.set(commit, []); continue; }
	const parts = line.split('\t');
	if (parts.length >= 2 && commit) byCommit.get(commit).push(parts);
}
for (const [c, changes] of byCommit) {
	const keptHere = new Set();
	for (const [status, a, b] of changes) {
		const p = status.startsWith('R') || status.startsWith('C') ? b : a;
		if ((status === 'A' || status.startsWith('R') || status.startsWith('C')) && isEntryPath(p)) {
			const id = idOf(show(c, p)); if (id) keptHere.add(id);
		}
	}
	for (const [status, oldPath, newPath] of changes) {
		// D removes the id; R moves the file and may change it; M may edit the id in place.
		if (!(status === 'D' || status === 'M' || status.startsWith('R')) || !isEntryPath(oldPath)) continue;
		const oldId = idOf(show(`${c}^`, oldPath));
		if (!oldId || keptHere.has(oldId) || retired.has(oldId)) continue;
		const to = status === 'D' ? null : idOf(show(c, status === 'M' ? oldPath : newPath));
		// Moved out of the catalogue - into docs/, say - retires the id even if the file still holds it.
		const stillEntry = status === 'M' || isEntryPath(newPath);
		if (status !== 'D' && to === oldId && stillEntry) continue;
		retired.set(oldId, { path: oldPath, commit: c, to });
	}
}

// The working tree is the newest point in history: an entry at HEAD whose id no current file holds
// is retired by the uncommitted change, so the gate run before a commit agrees with the one after.
const headIds = new Set([...current.keys()]);
for (const f of git('ls-tree', '-r', '--name-only', 'HEAD').split('\n').filter(isEntryPath)) {
	const id = idOf(show('HEAD', f));
	if (id && !headIds.has(id) && !retired.has(id)) retired.set(id, { path: f, commit: 'working-tree', to: null });
}

// Reuses that happened before this check existed. Each is a fact of history, not a permission:
// frozen records citing these ids before the date given mean the earlier entry.
const BEFORE_THIS_CHECK = {
	A0: 'a former axiom, A0 sovereign intelligence engine, removed 2026-08-21; A0 is now the axioms charter',
	C1: 'the catalogue-entry schema, renamed SC1 on 2026-08-20; C1 is now the AGP component',
};

if (process.env.LIST_RETIRED) for (const [id, w] of retired) console.log(`retired  ${id}  ${w.path}`);
let reused = 0;
for (const [id, where] of retired) {
	const now = current.get(id);
	if (!now || BEFORE_THIS_CHECK[id]) continue;
	console.log(`FAIL  reused  ${id} is held by ${now}, but was retired at ${where.commit.slice(0, 7)} (${where.path}${where.to ? ` -> ${where.to}` : ''})`);
	reused++;
}

// supersedes records lineage: the ids an entry replaces. A moved entry leaves no stub, so this is
// what a reader holding an old citation finds by searching for it. Each must name an id that
// history shows retired - neither a live id nor one never issued.
const ROOTS = readdirSync(ROOT, { withFileTypes: true }).filter((d) => d.isDirectory() && !d.name.startsWith('.') && d.name !== 'docs' && d.name !== 'node_modules');
let badLineage = 0;
for (const d of ROOTS) for (const f of readdirSync(path.join(ROOT, d.name))) {
	if (!f.endsWith('.md')) continue;
	const fm = /^---\n([\s\S]*?)\n---/.exec(readFileSync(path.join(ROOT, d.name, f), 'utf8'));
	const sup = fm && /^supersedes:\s*\[(.*)\]\s*$/m.exec(fm[1]);
	for (const id of (sup ? sup[1].split(',').map((s) => s.trim()).filter(Boolean) : [])) {
		if (retired.has(id) && !current.has(id)) continue;
		console.log(`FAIL  lineage  ${d.name}/${f} supersedes ${id}, which is ${current.has(id) ? 'a live entry' : 'not retired in history'}`);
		badLineage++;
	}
}

console.log(`${current.size} current ids, ${retired.size} retired in history.`);
if (badLineage) { console.log(`${badLineage} supersedes value(s) do not name a retired id.`); process.exit(1); }
if (reused) { console.log(`${reused} retired id(s) reissued; a retired id is never issued again.`); process.exit(1); }
console.log('no retired id is reissued.');

#!/usr/bin/env node
// generate-architecture - derive the structural sections of docs/ARCHITECTURE.md from the corpus.
//
// Sovereign duty: the current architecture's structure, derived and no other. AR1 forbids a
// hand-authored current projection, because a hand-written statement of where a system is drifts
// from the system. For a corpus the running system is the repository itself, so the structure is
// read from it: the layers from the root README's table, each layer's duty and the layers it draws
// on from its charter, its population from its directory, and the gate's checks from check-all.sh.
// The reasoning sections - identity, justification, alignment, risks - stay authored.
//
// Regions are delimited <!-- BEGIN GENERATED: architecture-<name> ... --> / <!-- END GENERATED:
// architecture-<name> -->.
//
// Usage:  node tools/generate-architecture.mjs           regenerate
//         node tools/generate-architecture.mjs --check   exit non-zero if a region is stale

import { readFileSync, writeFileSync, existsSync, readdirSync } from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const target = path.join(ROOT, 'docs/ARCHITECTURE.md');
const check = process.argv.includes('--check');
if (!existsSync(target)) { console.log('no docs/ARCHITECTURE.md; nothing to derive.'); process.exit(0); }

const read = (p) => readFileSync(path.join(ROOT, p), 'utf8');
const fm = (text) => {
	const m = /^---\n([\s\S]*?)\n---/.exec(text); if (!m) return {};
	const o = {}; for (const l of m[1].split('\n')) { const kv = /^([\w-]+):\s*(.*)$/.exec(l); if (kv) o[kv[1]] = kv[2].trim(); }
	return o;
};
const list = (v) => String(v || '').replace(/[[\]]/g, '').split(',').map((s) => s.trim()).filter(Boolean);

// The layer table in the root README is the authored list of layers; everything else is read.
const layers = [...read('README.md').matchAll(/^\| *`?([A-Z-]+)`? *\| *\[`([a-z-]+)\/`\]\([^)]*\) *\| *(.*?) *\|$/gm)]
	.map((m) => ({ prefix: m[1], dir: m[2], blurb: m[3] }));
const knowledge = layers.filter((l) => l.prefix !== '-');
const prefixOf = (id) => (/^([A-Z]+)\d/.exec(id) || [])[1];

const rowsKnowledge = knowledge.map((l) => {
	const charter = path.join(l.dir, 'README.md');
	const c = existsSync(path.join(ROOT, charter)) ? fm(read(charter)) : {};
	const duty = String(c.title || '').split(' - ').slice(1).join(' - ') || l.blurb;
	const members = readdirSync(path.join(ROOT, l.dir)).filter((f) => f.endsWith('.md') && f !== 'README.md')
		.filter((f) => { const e = fm(read(path.join(l.dir, f))); return e.id && e.status !== 'superseded'; }).length;
	const draws = [...new Set(list(c.related).map(prefixOf).filter((p) => p && p !== l.prefix))]
		.filter((p) => knowledge.some((k) => k.prefix === p)).map((p) => `\`${p}\``).join(', ') || '-';
	return `| \`${l.dir}/\` | \`${l.prefix}\` | ${duty.replace(/\|/g, '/')} | ${members} | ${draws} |`;
});
const tablesKnowledge = ['| Layer | Prefix | Duty, from its charter | Members | Draws on, from its charter |', '|---|---|---|---|---|', ...rowsKnowledge].join('\n');

const other = layers.filter((l) => l.prefix === '-').map((l) => {
	const n = l.dir === 'tools' ? readdirSync(path.join(ROOT, 'tools')).filter((f) => /\.(mjs|sh)$/.test(f)).length : null;
	return `| \`${l.dir}/\` | ${l.blurb.replace(/\|/g, '/')}${n !== null ? ` ${n} scripts.` : ''} |`;
});
const tableOther = ['| Layer | Duty |', '|---|---|', ...other].join('\n');

const checks = [...read('tools/check-all.sh').matchAll(/^run "([^"]+)" (.*)$/gm)]
	.map((m) => { const t = (/tools\/([\w.-]+)/.exec(m[2]) || [])[1] || 'schemas test suite'; return `| ${m[1]} | \`${t}\` |`; });
const tableChecks = ['| The gate holds | By |', '|---|---|', ...checks, '| every changed markdown file keeps the style rules a script can hold | the `s*` tools, on changed files |'].join('\n');

let text = readFileSync(target, 'utf8');
const next0 = text;
let missing = 0;
for (const [name, body] of [['layers', tablesKnowledge], ['other-layers', tableOther], ['checks', tableChecks]]) {
	const B = `<!-- BEGIN GENERATED: architecture-${name}. Run tools/generate-architecture.mjs; do not edit by hand. -->`;
	const E = `<!-- END GENERATED: architecture-${name} -->`;
	const i = text.indexOf(B), j = text.indexOf(E);
	if (i === -1 || j === -1) { console.log(`FAIL  docs/ARCHITECTURE.md has no ${name} region`); missing++; continue; }
	text = text.slice(0, i) + B + '\n' + body + '\n' + text.slice(j);
}
if (missing) process.exit(1);
if (check) {
	if (text !== next0) { console.log('FAIL  the derived sections of docs/ARCHITECTURE.md are stale; run tools/generate-architecture.mjs'); process.exit(1); }
	console.log(`architecture: ${knowledge.length} knowledge layers, ${other.length} others and ${checks.length} gate checks derived and current.`);
} else {
	if (text !== next0) writeFileSync(target, text);
	console.log(`architecture: ${knowledge.length} knowledge layers, ${other.length} others and ${checks.length} gate checks derived.`);
}

#!/usr/bin/env node
// skill-graph — lint the SKILL.md catalogue as a DAG and derive levels.
//
// The catalogue is a hierarchy expressed as EDGES, not numbered names. Each canonical SKILL.md may declare,
// in its `metadata`, `prerequisite:` (vertical: read-first) and `composes:` (a specialist system over the
// primitives it is built from). This lint makes those edges load-bearing instead of narrative:
//   - every prerequisite / composes target resolves to a real skill;
//   - the graph is acyclic;
//   - "level" is DERIVED (longest path from a root), never stored in a name;
//   - composes-vs-MODEL: each composed primitive's construct family actually appears in the skill's assets;
//   - every bundle's `skills:` entry resolves.
// Exit non-zero on any broken edge or cycle. Dependency-free (no YAML lib); lenient frontmatter parse.
//
// Usage:  node tools/skill-graph.mjs            (from the mission-kit root)

import { readFileSync, readdirSync, existsSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { loadCanonical as loadWorkGraphLifecycle, validateLifecycle as validateWorkGraphLifecycle } from '../skills/arc-lifecycle/assets/validate-workgraph-lifecycle.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SKILLS = path.join(ROOT, 'skills');
const BUNDLES = path.join(ROOT, 'bundles');

// --- parse the YAML frontmatter of a SKILL.md (name + the metadata edge fields), dependency-free ---
function parseSkill(file) {
	const text = readFileSync(file, 'utf8');
	const m = text.match(/^---\n([\s\S]*?)\n---/);
	if (!m) return null;
	const fm = m[1];
	const name = (fm.match(/^name:\s*(.+)$/m) || [])[1]?.trim();
	if (!name) return null;
	// edge fields may be top-level or nested under metadata: — match anywhere in the frontmatter
	const edges = (key) => {
		const v = (fm.match(new RegExp(`^\\s*${key}:\\s*(.+)$`, 'm')) || [])[1];
		if (!v) return [];
		return v.replace(/[\[\]]/g, '').split(',')
			.map((s) => s.trim())
			// keep bare skill-name tokens only (drop prose like "sysml-modelling skills (model-a-…, …)")
			.filter((s) => /^[a-z0-9-]+$/.test(s));
	};
	// model-asset: names the .sysml file(s) that ARE the composition (so the composes-vs-model check reads the
	// MODEL, not the dogfood scaffolding — well-formedness.sysml/procedure assets are always constraint/action defs).
	const files = (key) => {
		const v = (fm.match(new RegExp(`^\\s*${key}:\\s*(.+)$`, 'm')) || [])[1];
		if (!v) return [];
		return v.replace(/[\[\]]/g, '').split(',').map((s) => s.trim()).filter((s) => /^[\w.\-]+\.sysml$/.test(s));
	};
	return { name, prerequisite: edges('prerequisite'), composes: edges('composes'), modelAsset: files('model-asset') };
}

// --- collect every canonical skill (a folder containing SKILL.md with a name) ---
const skills = new Map();
for (const ent of readdirSync(SKILLS)) {
	const dir = path.join(SKILLS, ent);
	if (!statSync(dir).isDirectory()) continue;
	const sk = path.join(dir, 'SKILL.md');
	if (!existsSync(sk)) continue;
	const parsed = parseSkill(sk);
	if (!parsed) continue;
	if (parsed.name !== ent) console.warn(`WARN  ${ent}/SKILL.md declares name '${parsed.name}' (should match folder)`);
	skills.set(parsed.name, { ...parsed, dir });
}

const errors = [];
const edgesOf = (s) => [...s.prerequisite, ...s.composes];

// --- 1. every edge target resolves ---
for (const s of skills.values())
	for (const t of edgesOf(s))
		if (!skills.has(t)) errors.push(`unresolved edge: ${s.name} -> ${t} (no such skill)`);

// --- 2. acyclic + 3. derived level = longest path from a root (memoized DFS with cycle guard) ---
const level = new Map();
const onStack = new Set();
function depth(name, trail = []) {
	if (level.has(name)) return level.get(name);
	if (onStack.has(name)) { errors.push(`cycle: ${[...trail, name].join(' -> ')}`); return 0; }
	onStack.add(name);
	const s = skills.get(name);
	const parents = s ? edgesOf(s).filter((t) => skills.has(t)) : [];
	const d = parents.length ? 1 + Math.max(...parents.map((p) => depth(p, [...trail, name]))) : 0;
	onStack.delete(name);
	level.set(name, d);
	return d;
}
for (const name of skills.keys()) depth(name);

// --- 5. composes-vs-MODEL: each composed primitive's construct family must appear in the skill's assets ---
// Turns a `composes:` claim into a tested invariant (twin-parity — a declared edge + the model it claims must
// agree): a composed skill must
// actually use the construct of each primitive it claims to compose, or the composition is a paper claim.
const COMPOSES_CONSTRUCT = {
	'model-a-state-machine':    { re: /\bstate\s+def\b/,            what: 'a state def' },
	'model-a-workflow':         { re: /\baction\s+def\b/,           what: 'an action def' },
	'model-a-component':        { re: /\bpart\s+def\b/,             what: 'a part def' },
	'model-a-dependency-graph': { re: /\bref\s+\w+\s*:\s*\w+\s*\[/, what: 'a ref-edge with multiplicity' },
	'model-a-constraint':       { re: /\bconstraint\s+def\b/,       what: 'a constraint def' },
	'model-a-classification':   { re: /\benum\s+def\b/,             what: 'an enum def' },
};
for (const s of skills.values()) {
	if (!s.composes.length) continue;
	if (!s.modelAsset.length) {
		errors.push(`composes-vs-model: ${s.name} composes but declares no \`model-asset:\` (which asset(s) ARE the composition?)`);
		continue;
	}
	let blob = '';
	for (const fn of s.modelAsset) {
		const p = path.join(s.dir, 'assets', fn);
		if (existsSync(p)) blob += readFileSync(p, 'utf8') + '\n';
		else errors.push(`composes-vs-model: ${s.name} model-asset '${fn}' not found`);
	}
	// strip comments (block `/* */` incl. `doc`, and line `//`) so a construct merely NAMED in prose
	// doesn't satisfy the check — only a real declaration in code counts.
	blob = blob.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/\/\/[^\n]*/g, ' ');
	for (const c of s.composes) {
		const sig = COMPOSES_CONSTRUCT[c];
		if (sig && !sig.re.test(blob))
			errors.push(`composes-vs-model: ${s.name} composes '${c}' but no ${sig.what} appears in its model-asset(s)`);
	}
}

// --- 4. every bundle's skills: entry resolves ---
if (existsSync(BUNDLES)) {
	for (const f of readdirSync(BUNDLES).filter((f) => f.endsWith('.yaml') || f.endsWith('.yml'))) {
		const text = readFileSync(path.join(BUNDLES, f), 'utf8');
		const block = text.split(/^skills:\s*$/m)[1] || '';
		for (const line of block.split('\n')) {
			const mm = line.match(/^\s*-\s*([a-z0-9-]+)/);  // skip commented (#) / blank lines
			if (mm && !skills.has(mm[1])) errors.push(`bundle ${f}: lists '${mm[1]}' (no such skill)`);
		}
	}
}

// --- 6. canonical WorkGraph lifecycle + skill-selection routes stay aligned with this catalogue/bundle ---
try {
	const { lifecycle, selection } = loadWorkGraphLifecycle();
	for (const error of validateWorkGraphLifecycle(lifecycle, selection, { root: ROOT }))
		errors.push(`workgraph-lifecycle: ${error}`);
} catch (error) {
	errors.push(`workgraph-lifecycle: validator threw: ${error.message}`);
}

// --- report ---
const byLevel = [...skills.keys()].sort((a, b) => level.get(a) - level.get(b) || a.localeCompare(b));
console.log('skill graph — derived levels (L = longest prerequisite/composes path from a root):\n');
for (const name of byLevel) {
	const s = skills.get(name);
	const tags = [...s.prerequisite.map((p) => `prereq:${p}`), ...s.composes.map((c) => `composes:${c}`)];
	console.log(`  L${level.get(name)}  ${name}${tags.length ? '   (' + tags.join(', ') + ')' : ''}`);
}
console.log();
// Every skill directory must have a K* catalogue stub beside it, or it is loadable and
// invisible: absent from INDEX.md, unreachable by ID, and routed to by nothing.
for (const dir of readdirSync(SKILLS)) {
	const body = path.join(SKILLS, dir, 'SKILL.md');
	if (!existsSync(body)) continue;
	const stub = readdirSync(SKILLS).some((f) => /^K\d+-/.test(f) && f.endsWith(`-${dir}.md`));
	if (!stub) errors.push(`uncatalogued skill: skills/${dir}/ has no K* stub, so nothing can route to it`);
}

if (errors.length) { for (const e of errors) console.log(`FAIL  ${e}`); console.log(`\n${errors.length} error(s).`); process.exit(1); }
console.log(`PASS — ${skills.size} skills, graph acyclic, all edges + bundle entries resolve, composes-vs-model holds, WorkGraph lifecycle/selection conforms.`);

