      "description": "Discriminator. Identifies the document as an instance of this type.",
      "const": "standing-context"
    },
    "schema": {
      "description": "The contract this document claims to satisfy. A validator resolves its rules from here rather than assuming them.",
      "type": "string",
      "const": "urn:mission-kit:schemas:standing-context:standing-context:v1alpha1"
    },
    "knowledge-base": {
      "description": "Canonical address of the knowledge base this document routes to. A URL, so it resolves from any working directory on any host.",
      "type": "string",
      "format": "uri",
      "pattern": "^https://"
    },
    "forbids": {
      "description": "Terms that must not appear in the document body. These are the couplings this instance has ruled out of scope; naming them here is what lets the check be enforced without being hardcoded into the tool.",
