                "enum": [
                  "axiom",
                  "entity",
                  "component",
                  "artifact",
                  "trait"
                ]
              },
              "rationale": {
                "description": "Why this shape, in one sentence. A shape with no stated reason is a convention that nobody can argue with.",
                "type": "string",
                "minLength": 1
              },
