            "sections": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "minItems": 1
            },
            "exemptIds": {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          },
          "required": [
            "rationale",
            "sections"
          ],
          "additionalProperties": false
        }
      }
    }
  }
}

